use standout::{embed_styles, embed_templates, handler, InputSources, TargetProperties};

use units::ActiveState;
use view::UnitListView;

#[derive(Parser)]
#[command(name = "systemdlike", about = "Inspect the service manager's units")]
struct Cli {
